def fitm(fn,npar,trials=30):
    best=None
    for s in range(trials):
        p0=np.random.RandomState(s).rand(npar)*2
        try:
            r=least_squares(lambda p:fn(p)-sigma,p0,max_nfev=5000)
            if best is None or r.cost<best.cost: best=r
